<?php require '../config.php';$msg='';if($_SERVER['REQUEST_METHOD']==='POST'){$file=__DIR__.'/students.xml';if(!is_file($file))$msg='students.xml file not found in tasks folder.';else{$xml=simplexml_load_file($file);if(!$xml)$msg='Invalid XML.';else{$pdo->beginTransaction();try{$s=$pdo->prepare('INSERT INTO students(id,name,course) VALUES(?,?,?) ON DUPLICATE KEY UPDATE name=VALUES(name),course=VALUES(course)');foreach($xml->student as $st)$s->execute([(int)$st->id,(string)$st->name,(string)$st->course]);$pdo->commit();$msg='XML students imported into MySQL.';}catch(Throwable $e){$pdo->rollBack();$msg='Import failed. Check XML fields and database.';}}}}?><h1>Import students.xml to MySQL</h1><p><?=h($msg)?></p><form method="post"><button>Import XML</button></form><a href="../index.php">Home</a>